import {ToolRegistry} from './registry.js';

const schema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Array<Record<string, unknown>> = [];
    registry.register({name: 'get_weather', description: 'Weather', inputSchema: schema}, async input => {
      received.push(input);
      return 'sunny';
    });

    await registry.execute('get_weather', {location: 'Paris', units: 'metric'});

    expect(received).toEqual([{location: 'Paris', units: 'metric'}]);
  });

  it('validates a function-valued definition against the schema current at that call', async () => {
    const registry = new ToolRegistry();
    let current: Record<string, unknown> = schema;
    let executorCalls = 0;
    registry.register(
      () => ({name: 'get_weather', description: 'Weather', inputSchema: current}),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Paris'});
    current = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    const response = await registry.execute('get_weather', {location: 'Paris'});

    expect({executorCalls, rejectedNamingCity: response.result.includes('city')}).toEqual({
      executorCalls: 1,
      rejectedNamingCity: true,
    });
  });
});
